// Flag Identifier: someone saw a flag and can't look it up, so they describe
// it (what kind of flag it is, its layout, its colours, its other details) and
// we list the flags that fit. The per-flag descriptions are in
// data/flagIdentify.ts (generated by scripts/flag-identifier/build.mjs); this
// file holds the words people pick from and the ranking.
//
// Ranking, never filtering: one misremembered colour must not hide the
// answer. Every flag gets a count of differences from the description:
//   layout   each picked layout the flag doesn't have                  1
//   colours  each colour picked that the flag doesn't have, or each of
//            its main colours not picked, whichever is more            1
//            (so one colour remembered wrong is one difference)
//            a near colour, e.g. blue for light blue                   ½
//   details  each picked detail the flag doesn't have                  1
//            "None" when the flag has a symbol on it                   1
// Small or arguable things (a "?" in the data) count when picked and cost
// nothing when not. 0 differences fits the description; up to 1 is close.
// Ties are broken by how much of the flag went undescribed (each main layout
// or detail not picked 1, each small one ¼), so a flag that has exactly what
// was picked comes before one with extras, then by kind (a country before a
// region before a city…), so the flag most people mean comes first.
//
// The kind of flag ("I think it's a pride flag") is a boost, never a filter:
// flags of that kind are listed first, and every other flag that fits is still
// listed after them, in case the guess was wrong.

export type LayoutId =
  | "hstripes" | "vstripes" | "split" | "cross" | "nordic" | "saltire" | "diagonal" | "hoist"
  | "chevron" | "canton" | "unionjack" | "disc" | "diamond" | "border" | "plain" | "quartered" | "shape"
export type ColourId =
  | "red" | "maroon" | "pink" | "orange" | "yellow" | "green" | "lightblue" | "blue" | "purple" | "brown"
  | "white" | "grey" | "black"
export type DetailId =
  | "star" | "crescent" | "sun" | "cross" | "emblem" | "crown" | "animal" | "plant" | "weapon"
  | "building" | "person" | "writing" | "map" | "fleur" | "key" | "anchor" | "hand" | "heart" | "checkers"
  | "circle" | "triangle" | "manystripes"
/** A colour, or two names people use for the same colour ("blue|lightblue"). */
export type ColourSpec = ColourId | `${ColourId}|${ColourId}`

/** Kinds of flag the identifier searches, in the order a tie is broken (the
 *  flag most people mean first). A flag has one kind, and may also count as
 *  others (Scotland is a part of the UK that people call a country). */
export type IdentifyCategory = "country" | "region" | "city" | "identity" | "movement" | "organization" | "historical"
export const IDENTIFY_CATEGORIES: { id: IdentifyCategory; label: string; one: string; plural: string }[] = [
  { id: "country", label: "Country", one: "country flag", plural: "country flags" },
  { id: "region", label: "State, province or region", one: "state, province or region flag", plural: "state, province and region flags" },
  { id: "city", label: "City", one: "city flag", plural: "city flags" },
  { id: "identity", label: "Pride, peoples & identity", one: "pride, people or identity flag", plural: "pride, people and identity flags" },
  { id: "movement", label: "Separatist or movement", one: "separatist or movement flag", plural: "separatist and movement flags" },
  { id: "organization", label: "Organization", one: "organization flag", plural: "organization flags" },
  { id: "historical", label: "Historical", one: "historical flag", plural: "historical flags" },
]

export interface IdentifyEntry {
  code: string                 // country code (FlagImage, /flags/<code>/), or the flag's id in its own data
  name: string
  category: IdentifyCategory
  also?: IdentifyCategory[]    // other kinds people file it under
  label: string                // its kind, shown under the name: "US state", "Pride"
  img?: string                 // image, for flags that aren't countries
  note?: string                // a line about it, when its source data has one
  href?: string                // its page on the site, for flags that aren't countries
  layouts: LayoutId[]
  colors: ColourSpec[]         // the colours a person would name
  minorColors: ColourId[]      // small parts: inside a coat of arms, a thin crown
  details: DetailId[]
  minorDetails: DetailId[]
}

/** Whether a flag is of a kind, or counts as one. */
export const isKind = (e: IdentifyEntry, kind: IdentifyCategory) => e.category === kind || !!e.also?.includes(kind)
const KIND_ORDER = new Map(IDENTIFY_CATEGORIES.map((c, i) => [c.id, i]))

