/** The detail every flag with a layout has: the data adds it for them. */
export const LAYOUT_DETAIL: Partial<Record<LayoutId, DetailId>> = {
  cross: "cross", nordic: "cross", saltire: "cross", unionjack: "cross",
  hoist: "triangle", chevron: "triangle", disc: "circle",
}

/** Details that are part of the layout itself (Denmark's cross, Japan's
 *  disc). "None" means no symbols on the flag, so these don't count against it. */
export const STRUCTURAL: ReadonlySet<DetailId> = new Set<DetailId>(["cross", "circle", "triangle", "manystripes"])

/** Colours easy to mix up: picking one for the other costs half. */
const NEAR: Record<ColourId, ColourId[]> = {
  red: ["maroon", "orange", "pink"], maroon: ["red", "purple", "brown"], pink: ["red", "purple"],
  orange: ["red", "yellow", "brown"], yellow: ["orange"], green: [], lightblue: ["blue"],
  blue: ["lightblue", "purple"], purple: ["pink", "maroon", "blue"], brown: ["orange", "maroon"],
  white: ["grey"], grey: ["white", "black"], black: ["grey"],
}

export interface Answers {
  kind: IdentifyCategory | null  // null: not sure what kind of flag it is
  layouts: LayoutId[]        // empty: not answered or not sure
  colors: ColourId[]
  details: DetailId[]
  noDetails: boolean         // "None": the flag had nothing on it
}
export const NO_ANSWERS: Answers = { kind: null, layouts: [], colors: [], details: [], noDetails: false }
export const hasAnswers = (a: Answers) => a.layouts.length + a.colors.length + a.details.length > 0 || a.noDetails || a.kind !== null

export interface Match { entry: IdentifyEntry; diff: number; extras: number; misses: string[] }
const MINOR = 0.25

const names = (spec: ColourSpec) => spec.split("|") as ColourId[]
const colourLabel = (id: ColourId) => COLOURS.find(c => c.id === id)!.label.split(" or ")[0].toLowerCase()

export function scoreFlag(entry: IdentifyEntry, a: Answers): Match {
  let diff = 0, extras = 0
  const misses: string[] = []

  for (const l of a.layouts) {
    if (!entry.layouts.includes(l)) { diff += 1; misses.push(LAYOUTS.find(x => x.id === l)!.miss) }
  }
  if (a.layouts.length) extras += entry.layouts.filter(l => !a.layouts.includes(l)).length

  if (a.colors.length) {
    const main = entry.colors.flatMap(names)
    const has = new Set<ColourId>([...main, ...entry.minorColors])
    const wrong: ColourId[] = []
    for (const c of a.colors) {
      if (has.has(c)) continue
      const near = NEAR[c].find(n => has.has(n))
      if (near) { diff += 0.5; misses.push(`${colourLabel(near)}, not ${colourLabel(c)}`) }
      else wrong.push(c)
    }
    // A near colour covers one the flag has (blue for its light blue), unless
    // the flag has that colour too: red picked for a flag with red and pink
    // is its red, and the pink is still missing.
    const missing = entry.colors.map(names).filter(ids =>
      !ids.some(id => a.colors.includes(id) || NEAR[id].some(n => a.colors.includes(n) && !has.has(n)))).map(ids => ids[0])
    diff += Math.max(wrong.length, missing.length)
    for (let i = 0; i < Math.max(wrong.length, missing.length); i++) {
      misses.push(wrong[i] && missing[i] ? `${colourLabel(missing[i])}, not ${colourLabel(wrong[i])}`
        : wrong[i] ? `no ${colourLabel(wrong[i])}` : `also ${colourLabel(missing[i])}`)
    }
    extras += MINOR * entry.minorColors.filter(c => !a.colors.includes(c)).length
  }

  // A detail the picked layout already shows (a disc's circle) isn't left undescribed.
  const shown = (d: DetailId) => a.details.includes(d) || a.layouts.some(l => LAYOUT_DETAIL[l] === d)
  if (a.noDetails) {
    const symbols = entry.details.filter(d => !STRUCTURAL.has(d))
    if (symbols.length) { diff += 1; misses.push(`has ${DETAILS.find(x => x.id === symbols[0])!.has}`) }
    extras += entry.details.filter(d => STRUCTURAL.has(d) && !shown(d)).length + MINOR * entry.minorDetails.length
  } else if (a.details.length) {
    for (const d of a.details) {
      if (!entry.details.includes(d) && !entry.minorDetails.includes(d)) { diff += 1; misses.push(DETAILS.find(x => x.id === d)!.miss) }
    }
    extras += entry.details.filter(d => !shown(d)).length
    extras += MINOR * entry.minorDetails.filter(d => !a.details.includes(d)).length
  }
  return { entry, diff, extras, misses }
}

/** Every flag, best fit first: the picked kind first, then fewest
 *  differences, fewest extras, the kind most people mean, A–Z. */
export function rankFlags(entries: IdentifyEntry[], a: Answers): Match[] {
  const other = (e: IdentifyEntry) => a.kind && !isKind(e, a.kind) ? 1 : 0
  return entries.map(e => scoreFlag(e, a))
    .sort((x, y) => other(x.entry) - other(y.entry) || x.diff - y.diff || x.extras - y.extras
      || KIND_ORDER.get(x.entry.category)! - KIND_ORDER.get(y.entry.category)! || x.entry.name.localeCompare(y.entry.name))
}

/** How many differences still count as "close". */
export const CLOSE = 1

/** Everything the data says about a flag, as answers (used by the tests). */
export function describe(entry: IdentifyEntry, withMinor = false): Answers {
  const colors = [...new Set([...entry.colors.map(s => names(s)[0]), ...(withMinor ? entry.minorColors : [])])]
  const details = [...entry.details, ...(withMinor ? entry.minorDetails : [])]
  return { kind: null, layouts: [...entry.layouts], colors, details, noDetails: details.length === 0 }
}
